 return `<li class="jt-row jt-node jt-${kind}${ck?' has-checkin':''}"><div class="jt-time">${stopTimeMarkup(t,index,rrJourneyDay)}</div><div class="jt-spine jt-in-${spineIn} jt-out-${spineOut}" aria-hidden="true"><span class="jt-dot"></span></div><button type="button" class="jt-station stop-station" data-leg="${legIndex}" data-name="${encodeURIComponent(name)}" title="View station">${name}</button>${rrPlatformMarkup(rrPlatformAt(t,name),rrPlatformChangedFrom(t,name))}${ck?`<div class="jt-spine jt-in-${spineOut} jt-out-${spineOut} jt-spine-cont" aria-hidden="true"></div>${rrCheckInHint()}`:''}</li>`;
