function rrJourneyBoardDay(j,leg){const d=rrJourneyDate();d.setDate(d.getDate()+(j.whenTomorrow?1:0)+Math.floor(((j.legs[0].dep%1440)+(leg.dep-j.legs[0].dep))/1440));return d}
function fillJourneyDetails(j){rrJourneyDay=rrJourneyBase(j);
 rrDetailsHeading('Journey details','rr-ui-more');$('focusRoute').hidden=false;
 const from=j.legs[0].from,to=j.legs[j.legs.length-1].to;
 let rows='';
 j.legs.forEach((leg,index)=>{
  const t=leg.train,last=index===j.legs.length-1;
  const accent=`--leg:${rrTrainCss(t)}`;
  const calls=t.route.slice(leg.fromIdx+1,leg.toIdx);
  const callsId=`jt-calls-${index}`;
  const stopsLabel=calls.length?`${calls.length} ${calls.length===1?'stop':'stops'}`:'Non-stop';
  rows+=`<li class="jt-leg" style="${accent}"><ol class="jt-leg-list">`;
  rows+=rrJourneyNode(t,leg.fromIdx,leg.from,'board',index?'dot':'none','solid',index,leg.toIdx,rrJourneyBoardDay(j,leg));
  rows+=`<li class="jt-row jt-ride"><div class="jt-time"></div><div class="jt-spine jt-in-solid jt-out-solid" aria-hidden="true"></div><div class="jt-card">
   <h3 class="jt-card-head">${rrBadge(t,leg.from)}<span class="jt-service">${rrServiceLabel(t.type,t.network)}</span><span class="jt-status">${statusTag(stopStatus(t,leg.fromIdx))}${rrAlertTip(t,'jt-alert-'+index)}</span></h3>
   <div class="jt-towards">${t.ring?`<span>${rrDestText(t)}</span>${rrRingTag(t)}`:`<span class="jt-towards-label">towards</span> <span>${t.dest}</span>${rrFastTag(t)}`}</div>
   <div class="jt-meta"><span>${fmtDuration(leg.arr-leg.dep)}</span><span class="jt-sep" aria-hidden="true">·</span>${calls.length?`<button type="button" class="jt-calls-toggle" aria-expanded="false" aria-controls="${callsId}"><span>${stopsLabel}</span><span class="jt-chevron" aria-hidden="true"></span></button>`:`<span>${stopsLabel}</span>`}</div>
  </div></li>`;
  if(calls.length){
   rows+=`<li class="jt-calls" id="${callsId}" hidden><ol class="jt-calls-list">${calls.map(([name],i)=>{
    const k=leg.fromIdx+1+i;
    return `<li class="jt-row jt-call"><div class="jt-time">${stopTimeMarkup(t,k,rrJourneyDay)}</div><div class="jt-spine jt-in-solid jt-out-solid" aria-hidden="true"><span class="jt-tick"></span></div><button type="button" class="jt-station stop-station" data-leg="${index}" data-name="${encodeURIComponent(name)}" title="View station">${name}</button>${rrPlatformMarkup(t.platforms?.[name]||'',rrPlatformChangedFrom(t,name))}</li>`;
   }).join('')}</ol></li>`;
  }
  rows+=rrJourneyNode(t,leg.toIdx,leg.to,'alight','solid',last?'none':'dot',index);
  rows+=`</ol></li>`;
  if(!last){
   const next=j.legs[index+1],station=leg.to;
   const arrivalPlatform=rrPlatformAt(t,station)||'—',departurePlatform=rrPlatformAt(next.train,station)||'—';
   rows+=`<li class="jt-row jt-transfer"><div class="jt-time"></div><div class="jt-spine jt-in-dot jt-out-dot" aria-hidden="true"></div><div class="jt-transfer-box"><strong><svg class="rr-action-icon jt-change-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-ui-change-trains"></use></svg><span aria-hidden="true">Change</span><span class="rr-sr-only">Change at ${station}</span></strong><span class="transfer-detail">${next.dep-leg.arr} min</span></div></li>`;
  }
 });
 const depFirst=j.legs[0],arrLast=j.legs[j.legs.length-1];
 detail.innerHTML=`<div class="journey-hero"><div class="journey-summary-time"><div><strong>${stopTimeMarkup(depFirst.train,depFirst.fromIdx,rrJourneyDay)}</strong><small>Departs</small><span class="station">${from}</span></div><span class="arrow" aria-hidden="true"><svg class="rr-arrow-icon" aria-hidden="true" focusable="false" viewBox="0 0 32 32"><use href="#rr-picto-arrow-right"></use></svg></span><div class="journey-arrival"><strong>${stopTimeMarkup(arrLast.train,arrLast.toIdx,rrJourneyDay)}</strong><small>Arrives</small><span class="station">${to}</span></div></div><div class="journey-summary-sub">${fmtDuration(j.arr-j.dep)} · ${j.change?`${j.change} ${j.change===1?'change':'changes'}`:'Direct'}</div></div><ol class="jt-timeline" aria-label="Journey route">${rows}</ol>`;
 detail.querySelectorAll('.jt-calls-toggle').forEach(btn=>btn.addEventListener('click',()=>{
  const open=btn.getAttribute('aria-expanded')!=='true';
  btn.setAttribute('aria-expanded',String(open));
  document.getElementById(btn.getAttribute('aria-controls')).hidden=!open;
 }));
 rrWireTrainLinks(detail,j);rrWireAlertTips(detail);
 detail.querySelectorAll('.stop-station').forEach(btn=>btn.addEventListener('click',()=>{
  const name=decodeURIComponent(btn.dataset.name),returned=j;
  setCurrentStation(name);fillStationInfo(name,null,returned);
 }));
}
let rrStationMode='departures';   // Stations reopens departures or arrivals, as last chosen
$('stationsTab').addEventListener('click',()=>setViewMode(rrStationMode));
// as Depart after / Arrive by: choosing the tab already chosen does nothing (no redraw, the timetable keeps its place)
$('departuresTab').addEventListener('click',()=>{if(viewMode==='departures')return;rrStationMode='departures';setViewMode('departures')});
$('arrivalsTab').addEventListener('click',()=>{if(viewMode==='arrivals')return;rrStationMode='arrivals';setViewMode('arrivals')});
$('journeysTab').addEventListener('click',()=>setViewMode('journeys'));
// Filter existing results immediately; new stations still require Find trains.
$('directOnly').addEventListener('change',refreshJourneyFilters);
$('highSpeedOnly').addEventListener('change',refreshJourneyFilters);
$('journeyWhenTime').value=rrMinutesToInput(RR_NOW);
$('journeyWhenDate').value=$('journeyWhenDate').min=rrIsoDate(rrDay(0));rrSyncWhenDate();
$('journeyWhenDate').addEventListener('change',()=>{if(!$('journeyWhenDate').value||$('journeyWhenDate').value<$('journeyWhenDate').min)$('journeyWhenDate').value=$('journeyWhenDate').min;rrSyncWhenDate();rrJourneyWhenChanged()});
$('journeyWhenDate').addEventListener('click',e=>{try{e.target.showPicker()}catch(_){}});
function rrJourneyWhenChanged(){if(!appliedJourneyQuery)return;journeyShown=12;renderJourneyResults();board.scrollTop=rrJourneyWhen().mode==='arrive'?board.scrollHeight:0}
$('journeyWhenMode').addEventListener('change',()=>{rrSyncWhenTabs();rrJourneyWhenChanged()});
document.querySelectorAll('.rr-when-tab').forEach(b=>b.addEventListener('click',()=>{if($('journeyWhenMode').value===b.dataset.when)return;$('journeyWhenMode').value=b.dataset.when;$('journeyWhenMode').dispatchEvent(new Event('change'))}));
$('journeyWhenTime').addEventListener('change',()=>rrJourneyWhenChanged());
$('journeyWhenNow').addEventListener('click',()=>{$('journeyWhenMode').value='depart';$('journeyWhenDate').value=rrIsoDate(rrDay(0));rrSyncWhenDate();$('journeyWhenTime').value=rrMinutesToInput(rrNowMinutes());rrJourneyWhenChanged()});
// Keep the clock moving: refresh live status every minute, and start a new
// day's running pattern after midnight.
// Re-render an open train or journey panel when its live status changes,
// keeping the scroll position and any sections the viewer has opened.
function rrRefreshOpenDetails(){
 const top=detail.scrollTop;
 if(selectedTrain&&!selectedTrain.tomorrow&&detail.querySelector('.train-hero')){
  const live=TRAINS.find(x=>x.id===selectedTrain.id);if(live)selectedTrain.status=live.status;
  fillDetails(selectedTrain);
 }else if(selectedJourney&&detail.querySelector('.jt-timeline')){
  const calls=[...detail.querySelectorAll('.jt-calls-toggle')].map(b=>b.getAttribute('aria-expanded')==='true');
  fillJourneyDetails(selectedJourney);
  detail.querySelectorAll('.jt-calls-toggle').forEach((b,i)=>{if(calls[i])b.click()});
 }else return;
 detail.scrollTop=top;
}
setInterval(()=>{
 const before=TRAINS.map(t=>t.status).join('|');
 const key=rrDateKey(rrNow());RR_NOW=rrNowMinutes();
 if(key!==RR_DAY_KEY){RR_DAY_KEY=key;rrApplyDailyOperations();rrAssignDailyAlerts()}else rrRefreshLiveStatus();
 if(viewMode!=='journeys'){const top=board.scrollTop;drawBoard();board.scrollTop=top}
 if(TRAINS.map(t=>t.status).join('|')!==before)rrRefreshOpenDetails();
},60000);
$('trace').onclick=()=>searchJourneys();
// Reset: an empty planner in its default state (From / To cleared, Depart after, now, no filters), still on Journeys
// (user 2026-11-21: it used to go back to the Stations tab)
$('clear').onclick=()=>{
 appliedJourneyQuery=null;journeyResults=[];journeyEditing=false;selectedJourney=null;selectedLegPaths=[];selectedRouteLine=null;
 for(const id of ['from','to']){rrSelectValue($(id),'');pickerViews.get(id)?.sync()}
 $('journeyWhenNow').click();$('directOnly').checked=false;$('highSpeedOnly').checked=false;
 clear();app.classList.remove('detail-open');setViewMode('journeys');rrSyncHash();
};
// Swap the draft station values without changing the displayed results.
$('swapStations').addEventListener('click',()=>{
 // the selects only hold the chosen station, so set each through rrSelectValue (adds the option first)
 const from=$('from'),to=$('to'),previousFrom=from.value;
 rrSelectValue(from,to.value);rrSelectValue(to,previousFrom);
 pickerViews.get('from')?.sync();
 pickerViews.get('to')?.sync();
});

stationSelect.addEventListener('change',e=>setCurrentStation(e.target.value));
// Departures / arrivals: back to choosing a station (user 2026-11-20: "add a reset button to go back to station selection")
$('stationReset').addEventListener('click',()=>{setCurrentStation(null);pickerViews.get('stationSelect')?.sync();document.querySelector('.search-picker-main input')?.focus({preventScroll:true})});
function rrSetFolded(is,persist=true){
 app.classList.toggle('folded',is);
 const control=$('collapse');
 const action=is?'Expand departures':'Collapse departures';
 control.setAttribute('aria-label',action);
 control.setAttribute('aria-expanded',String(!is));
 control.title=action+' ( [ )';
 if(persist){try{localStorage.setItem('rrSidebarFolded',is?'1':'0')}catch(e){}}
 setTimeout(resize,220);
}
$('collapse').onclick=()=>rrSetFolded(!app.classList.contains('folded'));
try{if(localStorage.getItem('rrSidebarFolded')==='1'&&!window.matchMedia('(max-width:750px)').matches)rrSetFolded(true,false)}catch(e){}
document.addEventListener('keydown',e=>{
 if(e.key!=='['||e.metaKey||e.ctrlKey||e.altKey)return;
 const t=e.target;if(t&&(t.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)))return;
 e.preventDefault();rrSetFolded(!app.classList.contains('folded'));
});
$('closeDetail').onclick=()=>{if(selectedRouteLine||rrLocalSystem||rrFocusSystem){clear();rrApplySystemFocus()}app.classList.remove('detail-open');requestAnimationFrame(resize);rrSyncHash()};   // a line shown from route details goes with the panel
const ro=new ResizeObserver(()=>resize());ro.observe(container);

/* v46: relocate the functional From/To planner under mobile timetable. */
const rrPlannerMobileQuery=window.matchMedia('(max-width:750px)');
const rrPlannerTools=document.querySelector('.map-tools');
function rrPlacePlanner(){
 const parent=document.getElementById('journeyPlannerSlot');   // the planner belongs to the Journeys tab on every screen size
 const actions=rrPlannerTools.querySelector('.map-actions')||document.querySelector('.map-actions');
 const actionsHome=document.getElementById('journeyActionsSlot');
 if(actions&&actionsHome&&actions.parentElement!==actionsHome)actionsHome.append(actions);
 if(rrPlannerTools.parentElement!==parent){
  pickerViews.get('from')?.shut();pickerViews.get('to')?.shut();
  parent.append(rrPlannerTools);
 }
}
rrPlacePlanner();
rrPlannerMobileQuery.addEventListener('change',()=>{rrPlacePlanner();requestAnimationFrame(resize)});

pathsByType();stationList();
{const AIR=new Set(RR_STATION_NAMES.filter(rrIsAirport));   // any HTML text that is exactly an airport's name gets the glyph (the map draws its own)
 const mark=t=>{if(t.parentElement?.closest('.station-conn'))return;const v=t.data.trim();if(AIR.has(v))t.data=t.data.replace(v,v+RR_AIR)};   // not in Connections: the airport pictogram is already there (user 2026-11-22)
 const scan=el=>{const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);for(let t=w.nextNode();t;t=w.nextNode())mark(t)};
 new MutationObserver(rs=>{for(const r of rs)for(const n of r.addedNodes){if(n.nodeType===3){if(!(n.parentNode instanceof SVGElement))mark(n)}else if(n.nodeType===1&&!(n instanceof SVGElement))scan(n)}}).observe(document.body,{childList:true,subtree:true});
 scan(document.body)}
['stationSelect','from','to'].forEach(setupSearchPicker);updateBoardTabs();setCurrentStation(currentStation);resize();   // one map draw at boot (resize draws it)
